-- ===== 2. Rotate Array by k (topic 1, EASY) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 1, 'Rotate Array by k', 'rotate-array', 'EASY',
'Shift every element of an array `k` places to the **right**. An element pushed past the last position wraps around to the front. Print the array after the shift.

`k` can be zero, and it can be much larger than the array length.

**Constraints:** 1 <= n <= 100000, 0 <= k <= 10^9, -10^9 <= nums[i] <= 10^9.',
'Line 1: n and k separated by a space
Line 2: n space-separated integers',
'The n rotated values on one line, separated by single spaces',
2000, 500, 900
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'rotate-array');

-- SAMPLE #1: typical rotation
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, '5 2
10 20 30 40 50
', '40 50 10 20 30
', NULL
FROM problems p WHERE p.slug = 'rotate-array'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: rotate by one
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 2, '3 1
4 8 15
', '15 4 8
', NULL
FROM problems p WHERE p.slug = 'rotate-array'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 2);

-- EDGE #3: single element with k > 0: catches index arithmetic that assumes n >= 2
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 3, '1 5
42
', '42
', NULL
FROM problems p WHERE p.slug = 'rotate-array'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 3);

-- EDGE #4: k = 0: catches an off-by-one shift when nothing should move
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 4, '4 0
6 2 9 1
', '6 2 9 1
', NULL
FROM problems p WHERE p.slug = 'rotate-array'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 4);

-- BOUNDARY #5: k == n: catches not reducing k mod n (result must equal the input)
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 5, '6 6
1 2 3 4 5 6
', '1 2 3 4 5 6
', NULL
FROM problems p WHERE p.slug = 'rotate-array'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 5);

-- BOUNDARY #6: k much larger than n: catches k >= n not reduced (overflow or timeout)
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 6, '6 1000000000
3 1 4 1 5 9
', '4 1 5 9 3 1
', NULL
FROM problems p WHERE p.slug = 'rotate-array'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 6);

