-- ===== 3. Valid Anagram (topic 2, EASY) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 2, 'Valid Anagram', 'valid-anagram', 'EASY',
'Two words are anagrams when one can be turned into the other by reordering its letters, using every letter exactly as many times as it appears. Decide whether `s` and `t` are anagrams.

Two empty strings count as anagrams of each other.

**Constraints:** 0 <= |s|, |t| <= 200000; both contain only lowercase English letters.',
'Line 1: s (may be empty)
Line 2: t (may be empty)',
'true or false',
2000, 500, 600
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'valid-anagram');

-- SAMPLE #1: anagram pair
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, 'dusty
study
', 'true
', NULL
FROM problems p WHERE p.slug = 'valid-anagram'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: not an anagram
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 2, 'rocket
socket
', 'false
', NULL
FROM problems p WHERE p.slug = 'valid-anagram'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 2);

-- EDGE #3: both strings empty: catches failing on empty lines
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 3, '

', 'true
', NULL
FROM problems p WHERE p.slug = 'valid-anagram'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 3);

-- EDGE #4: same letters, different counts: catches comparing letter sets instead of counts
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 4, 'aab
abb
', 'false
', NULL
FROM problems p WHERE p.slug = 'valid-anagram'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 4);

-- BOUNDARY #5: one string is a prefix of the other: catches skipping the length check
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 5, 'abcd
abc
', 'false
', NULL
FROM problems p WHERE p.slug = 'valid-anagram'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 5);

-- BOUNDARY #6: only the last character differs: catches a loop that stops one early
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 6, 'abcdefgz
abcdefgy
', 'false
', NULL
FROM problems p WHERE p.slug = 'valid-anagram'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 6);

-- LARGE #7: length 150000: correctness at scale (no reliable naive/optimal split, see notes)
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'LARGE', 7, '

', 'true
', NULL
FROM problems p WHERE p.slug = 'valid-anagram'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 7);

-- ===== 4. Longest Common Prefix (topic 2, EASY) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 2, 'Longest Common Prefix', 'longest-common-prefix', 'EASY',
'Given a list of words, find the longest string that every word starts with.

The answer is printed inside square brackets so that an empty answer is still visible: a common prefix `ab` prints as `[ab]`, and no common prefix prints as `[]`.

**Constraints:** 1 <= n <= 10^4; each word has 0 to 200000 lowercase letters; the total length of all words is at most 400000.',
'Line 1: n
Next n lines: one word per line (a line may be empty)',
'The prefix wrapped in square brackets, e.g. [ab] or []',
2000, 500, 600
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'longest-common-prefix');

-- SAMPLE #1: typical prefix
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, '3
interview
internet
interval
', '[inter]
', NULL
FROM problems p WHERE p.slug = 'longest-common-prefix'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: short prefix
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 2, '3
cobalt
copper
coral
', '[co]
', NULL
FROM problems p WHERE p.slug = 'longest-common-prefix'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 2);

-- EDGE #3: a single word: catches comparing words[0] with a missing words[1]
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 3, '1
solo
', '[solo]
', NULL
FROM problems p WHERE p.slug = 'longest-common-prefix'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 3);

-- EDGE #4: one word is empty: catches assuming every word has a first character
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 4, '3
abc

abd
', '[]
', NULL
FROM problems p WHERE p.slug = 'longest-common-prefix'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 4);

-- BOUNDARY #5: shortest word is the whole prefix: catches reading past the end of the shortest word
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 5, '3
flowerbed
flow
flowery
', '[flow]
', NULL
FROM problems p WHERE p.slug = 'longest-common-prefix'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 5);

-- BOUNDARY #6: all words identical: catches stopping one character before the end
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 6, '3
same
same
same
', '[same]
', NULL
FROM problems p WHERE p.slug = 'longest-common-prefix'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 6);

-- LARGE #7: two words of 190000 chars sharing 189999: correctness at scale (no reliable split, see notes)
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'LARGE', 7, '2


', '[]
', NULL
FROM problems p WHERE p.slug = 'longest-common-prefix'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 7);

-- ===== 5. Pair With Target Sum in Sorted Array (topic 3, EASY) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 3, 'Pair With Target Sum in Sorted Array', 'pair-target-sum-sorted', 'EASY',
'The array `nums` is sorted in non-decreasing order. Find two **different** positions `i < j` whose values add up to `target`, and print `i j` (0-based). If no such pair exists, print `-1 -1`.

At most one pair of positions works, so the answer is unique.

**Constraints:** 1 <= n <= 100000, -10^8 <= nums[i], target <= 10^8.',
'Line 1: n
Line 2: n space-separated integers in non-decreasing order
Line 3: target',
'Two integers i and j separated by a space, or -1 -1',
2000, 500, 600
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'pair-target-sum-sorted');

-- SAMPLE #1: pair exists
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, '5
1 4 6 9 13
19
', '2 4
', NULL
FROM problems p WHERE p.slug = 'pair-target-sum-sorted'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: no pair
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 2, '4
2 5 8 12
11
', '-1 -1
', NULL
FROM problems p WHERE p.slug = 'pair-target-sum-sorted'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 2);

-- EDGE #3: single element: catches using the same element twice (l <= r)
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 3, '1
4
8
', '-1 -1
', NULL
FROM problems p WHERE p.slug = 'pair-target-sum-sorted'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 3);

-- EDGE #4: negative values: catches moving the wrong pointer when sums are negative
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 4, '5
-8 -3 0 5 11
-11
', '0 1
', NULL
FROM problems p WHERE p.slug = 'pair-target-sum-sorted'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 4);

-- BOUNDARY #5: pair is the first and last index: catches pointers starting inside the array
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 5, '5
3 7 8 10 20
23
', '0 4
', NULL
FROM problems p WHERE p.slug = 'pair-target-sum-sorted'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 5);

-- BOUNDARY #6: pair is the last two elements: catches a loop that stops when r = l + 1
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 6, '5
1 2 4 30 41
71
', '3 4
', NULL
FROM problems p WHERE p.slug = 'pair-target-sum-sorted'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 6);

