2 -1 3 8 -4 5 1
', '10
', 'STATE_TRANSITION'
FROM problems p WHERE p.slug = 'max-sum-subarray-size-k'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

