-- ===== 8. Longest Substring Without Repeating Characters (topic 4, MEDIUM) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 4, 'Longest Substring Without Repeating Characters', 'longest-substring-no-repeat', 'MEDIUM',
'Find the length of the longest **contiguous** piece of the string in which no character appears twice. An empty string has answer 0.

**Constraints:** 0 <= |s| <= 400000; s contains only English letters and digits (no spaces).',
'Line 1: s (may be empty)',
'A single integer: the length of the longest repeat-free substring',
2000, 500, 1800
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'longest-substring-no-repeat');

-- SAMPLE #1: typical string
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, 'pqrpqrs
', '4
', 'STATE_TRANSITION'
FROM problems p WHERE p.slug = 'longest-substring-no-repeat'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: letters repeat far apart
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 2, 'mississippi
', '3
', 'STATE_TRANSITION'
FROM problems p WHERE p.slug = 'longest-substring-no-repeat'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 2);

-- EDGE #3: empty string: catches assuming at least one character
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 3, '
', '0
', NULL
FROM problems p WHERE p.slug = 'longest-substring-no-repeat'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 3);

-- EDGE #4: all characters equal: catches a window that never shrinks
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 4, 'kkkkkk
', '1
', NULL
FROM problems p WHERE p.slug = 'longest-substring-no-repeat'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 4);

-- BOUNDARY #5: longest run ends at the last char: catches updating best only on a repeat
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 5, 'aabcdef
', '6
', NULL
FROM problems p WHERE p.slug = 'longest-substring-no-repeat'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 5);

-- BOUNDARY #6: repeat older than the window: catches moving the left edge backwards
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 6, 'abxyyab
', '4
', 'STATE_TRANSITION'
FROM problems p WHERE p.slug = 'longest-substring-no-repeat'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 6);

