-- ===== 17. Shortest Palindrome (topic 2, HARD) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 2, 'Shortest Palindrome', 'shortest-palindrome', 'HARD',
'You may only **add characters to the front** of the string `s`. Find the shortest palindrome you can make this way and print it.

A palindrome reads the same forwards and backwards. The empty string is a palindrome.

**Constraints:** 0 <= |s| <= 200000; s contains only lowercase English letters.',
'Line 1: s (may be empty)',
'The shortest palindrome wrapped in square brackets, e.g. [abba] or []',
2000, NULL, 2400
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'shortest-palindrome');

-- SAMPLE #1: a long palindromic prefix
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, 'aacecaaa
', '[aaacecaaa]
', NULL
FROM problems p WHERE p.slug = 'shortest-palindrome'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: no palindromic prefix longer than one letter
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 2, 'abcd
', '[dcbabcd]
', NULL
FROM problems p WHERE p.slug = 'shortest-palindrome'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 2);

-- EDGE #3: empty string
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 3, '
', '[]
', NULL
FROM problems p WHERE p.slug = 'shortest-palindrome'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 3);

-- EDGE #4: single letter
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 4, 'a
', '[a]
', NULL
FROM problems p WHERE p.slug = 'shortest-palindrome'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 4);

-- BOUNDARY #5: already a palindrome: nothing to add
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 5, 'racecar
', '[racecar]
', NULL
FROM problems p WHERE p.slug = 'shortest-palindrome'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 5);

-- BOUNDARY #6: repeated letters then a different one
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 6, 'aaaaab
', '[baaaaab]
', NULL
FROM problems p WHERE p.slug = 'shortest-palindrome'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 6);

-- LARGE #7: length 200000: checking every prefix is O(n^2); KMP / prefix function is O(n)
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'LARGE', 7, '
', '[]
', NULL
FROM problems p WHERE p.slug = 'shortest-palindrome'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 7);

-- ===== 18. Trapping Rain Water (topic 3, HARD) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 3, 'Trapping Rain Water', 'trapping-rain-water', 'HARD',
'Bars of width 1 stand side by side with the given heights. After heavy rain, water collects in the dips between taller bars. How many units of water stay trapped?

Above each bar the water level is the **lower** of the tallest bar to its left and the tallest bar to its right; water never rests above the outermost bars.

**Constraints:** 1 <= n <= 100000, 0 <= height[i] <= 10^6. The answer may not fit in a 32-bit int.',
'Line 1: n
Line 2: n space-separated integers (the heights)',
'A single integer: the trapped water',
2000, NULL, 2400
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'trapping-rain-water');

-- SAMPLE #1: several pools
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, '12
0 1 0 2 1 0 1 3 2 1 2 1
', '6
', NULL
FROM problems p WHERE p.slug = 'trapping-rain-water'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: one wide basin
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
