-- ===== 29. Is It a Valid Search Tree? (topic 8, MEDIUM) =====
INSERT INTO problems (topic_id, title, slug, difficulty, statement, input_format, output_format,
                      time_limit_ms, optimal_runtime_ms, target_solve_seconds)
SELECT 8, 'Is It a Valid Search Tree?', 'validate-binary-search-tree', 'MEDIUM',
'A binary tree is a valid **binary search tree** when, for every node, **all** values in its left subtree are smaller than the node and **all** values in its right subtree are larger. Equal values are not allowed.

Checking only each node''s direct children is not enough: a value deep in the left subtree must still be smaller than every ancestor it sits to the left of.

**Constraints:** 1 <= nodes <= 60000, -10^9 <= value <= 10^9. The tree is given in level order, where `null` marks a missing child.',
'Line 1: m, the number of tokens
Line 2: m space-separated tokens, each an integer or null',
'true or false',
2000, NULL, 1200
WHERE NOT EXISTS (SELECT 1 FROM problems WHERE slug = 'validate-binary-search-tree');

-- SAMPLE #1: a small valid tree
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 1, '3
2 1 3
', 'true
', NULL
FROM problems p WHERE p.slug = 'validate-binary-search-tree'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 1);

-- SAMPLE #2: a right child smaller than the root
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'SAMPLE', 2, '7
5 1 4 null null 3 6
', 'false
', NULL
FROM problems p WHERE p.slug = 'validate-binary-search-tree'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 2);

-- EDGE #3: a single node
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 3, '1
7
', 'true
', NULL
FROM problems p WHERE p.slug = 'validate-binary-search-tree'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 3);

-- EDGE #4: equal values are not allowed
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'EDGE', 4, '2
2 2
', 'false
', NULL
FROM problems p WHERE p.slug = 'validate-binary-search-tree'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 4);

-- BOUNDARY #5: a grandchild breaks the rule: catches checking only direct children
INSERT INTO test_cases (problem_id, tag, ordinal, input, expected_output, error_category_override)
SELECT p.id, 'BOUNDARY', 5, '7
5 4 6 null null 3 7
', 'false
', NULL
FROM problems p WHERE p.slug = 'validate-binary-search-tree'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 5);

