0 -1000000000 1000000000 null -999999999
', 'true
', NULL
FROM problems p WHERE p.slug = 'validate-binary-search-tree'
AND NOT EXISTS (SELECT 1 FROM test_cases t WHERE t.problem_id = p.id AND t.ordinal = 6);

